// Process incoming email verification request
const inputData = $input.first().json;
const requestData = inputData.body || inputData;

try {
  if (!requestData.batchId) {
    throw new Error('batchId is required');
  }

  let emails = [];

  if (typeof requestData.emails === 'string') {
    emails = JSON.parse(requestData.emails);
  } else if (Array.isArray(requestData.emails)) {
    emails = requestData.emails;
  } else {
    throw new Error('emails must be an array or JSON string');
  }

  console.log(`Processing ${emails.length} emails for verification`);

  return emails.map(email => ({
    json: {
      ...email,
      batchId: requestData.batchId,
      verificationStatus: 'pending'
    }
  }));

} catch (error) {
  console.error('Input validation error:', error.message);
  throw error;
}

// NeverBounce API verification
const emailData = $input.item.json;
const email = emailData.email;

console.log(`[NeverBounce] Verifying ${email}`);

// Simulate NeverBounce API call
// In production: POST to https://api.neverbounce.com/v4/single/check

const results = ['valid', 'invalid', 'disposable', 'catchall', 'unknown'];
const result = results[Math.floor(Math.random() * results.length)];

// Weighted towards valid for demo
const nbResult = Math.random() > 0.3 ? 'valid' : result;

const neverBounceResponse = {
  email: email,
  result: nbResult,
  flags: {
    hasMailServer: nbResult !== 'invalid',
    hasDNS: nbResult !== 'invalid',
    freeEmail: email.includes('gmail') || email.includes('yahoo') || email.includes('hotmail'),
    roleAccount: email.startsWith('info@') || email.startsWith('admin@') || email.startsWith('contact@')
  },
  suggestedCorrection: null,
  executionTime: Math.floor(Math.random() * 500) + 100
};

if (nbResult === 'invalid' && Math.random() > 0.7) {
  neverBounceResponse.suggestedCorrection = email.replace('.co', '.com');
}

return [{
  json: {
    ...emailData,
    neverBounce: neverBounceResponse,
    verificationProgress: 33
  }
}];

// Debounce.io API verification
const emailData = $input.item.json;
const email = emailData.email;

console.log(`[Debounce.io] Verifying ${email}`);

// Simulate Debounce.io API call
// In production: GET to https://api.debounce.io/v1/

const results = ['Safe', 'Risky', 'Invalid', 'Unknown'];
const debounceResult = Math.random() > 0.25 ? 'Safe' : results[Math.floor(Math.random() * results.length)];

const debounceResponse = {
  email: email,
  result: debounceResult,
  reason: debounceResult === 'Invalid' ? 'Invalid mailbox' : 
          debounceResult === 'Risky' ? 'Potential spam trap' :
          debounceResult === 'Unknown' ? 'Cannot verify' : 'Valid mailbox',
  sendAssess: debounceResult === 'Safe' ? 1 : debounceResult === 'Risky' ? 0.5 : 0,
  spamTrap: debounceResult === 'Risky' && Math.random() > 0.7,
  complainer: Math.random() > 0.9,
  syntax: {
    valid: !debounceResult.includes('Invalid'),
    username: email.split('@')[0],
    domain: email.split('@')[1]
  }
};

return [{
  json: {
    ...emailData,
    debounce: debounceResponse,
    verificationProgress: 66
  }
}];

// ZeroBounce API verification
const emailData = $input.item.json;
const email = emailData.email;

console.log(`[ZeroBounce] Verifying ${email}`);

// Simulate ZeroBounce API call
// In production: GET to https://api.zerobounce.net/v2/validate

const statuses = ['valid', 'invalid', 'catch-all', 'unknown', 'spamtrap', 'abuse', 'do_not_mail'];
const zbStatus = Math.random() > 0.25 ? 'valid' : statuses[Math.floor(Math.random() * statuses.length)];

const zeroBounceResponse = {
  email: email,
  status: zbStatus,
  subStatus: zbStatus === 'invalid' ? 'mailbox_not_found' :
             zbStatus === 'catch-all' ? 'accept_all' : '',
  account: email.split('@')[0],
  domain: email.split('@')[1],
  didYouMean: null,
  domainAgeDays: Math.floor(Math.random() * 3650) + 365,
  freeEmail: email.includes('gmail') || email.includes('yahoo') || email.includes('hotmail'),
  mxFound: zbStatus !== 'invalid',
  mxRecord: zbStatus !== 'invalid' ? `mx.${email.split('@')[1]}` : null,
  smtpProvider: ['Google', 'Microsoft', 'GoDaddy', 'Generic'][Math.floor(Math.random() * 4)],
  firstname: emailData.personName?.split(' ')[0] || null,
  lastname: emailData.personName?.split(' ')[1] || null,
  gender: Math.random() > 0.5 ? 'male' : 'female',
  country: 'US',
  region: 'Texas',
  city: 'Austin',
  zipcode: null,
  processedAt: new Date().toISOString()
};

if (zbStatus === 'invalid' && Math.random() > 0.6) {
  zeroBounceResponse.didYouMean = email.replace(/\.(com|net|org)$/, '.com');
}

return [{
  json: {
    ...emailData,
    zeroBounce: zeroBounceResponse,
    verificationProgress: 100
  }
}];

// Calculate confidence score from all three services
const emailData = $input.item.json;
const email = emailData.email;

const nb = emailData.neverBounce;
const db = emailData.debounce;
const zb = emailData.zeroBounce;

// Scoring algorithm
let validCount = 0;
let totalWeight = 0;
let confidence = 0;
const issues = [];
const strengths = [];

// NeverBounce analysis (weight: 35%)
if (nb.result === 'valid') {
  validCount++;
  totalWeight += 35;
  strengths.push('NeverBounce: Valid');
} else if (nb.result === 'catchall') {
  totalWeight += 15;
  issues.push('Catch-all server detected (NeverBounce)');
} else if (nb.result === 'invalid') {
  issues.push('Invalid mailbox (NeverBounce)');
} else {
  totalWeight += 10;
  issues.push('Unknown status (NeverBounce)');
}

// Debounce.io analysis (weight: 35%)
if (db.result === 'Safe') {
  validCount++;
  totalWeight += 35;
  strengths.push('Debounce.io: Safe');
} else if (db.result === 'Risky') {
  totalWeight += 15;
  issues.push('Risky email (Debounce.io)');
  if (db.spamTrap) {
    issues.push('Potential spam trap');
    totalWeight -= 10;
  }
} else if (db.result === 'Invalid') {
  issues.push('Invalid email (Debounce.io)');
} else {
  totalWeight += 10;
  issues.push('Unknown status (Debounce.io)');
}

// ZeroBounce analysis (weight: 30%)
if (zb.status === 'valid') {
  validCount++;
  totalWeight += 30;
  strengths.push('ZeroBounce: Valid');
} else if (zb.status === 'catch-all') {
  totalWeight += 12;
  issues.push('Catch-all server (ZeroBounce)');
} else if (zb.status === 'invalid') {
  issues.push('Invalid mailbox (ZeroBounce)');
} else if (zb.status === 'spamtrap' || zb.status === 'abuse') {
  issues.push(`Dangerous: ${zb.status}`);
  totalWeight -= 20;
} else {
  totalWeight += 10;
  issues.push('Unknown status (ZeroBounce)');
}

// Additional factors
if (nb.flags?.freeEmail || zb.freeEmail) {
  issues.push('Free email provider');
  totalWeight -= 5;
}

if (nb.flags?.roleAccount) {
  issues.push('Role-based email (info@, admin@, etc.)');
  totalWeight -= 10;
}

if (zb.mxFound && nb.flags?.hasMailServer) {
  strengths.push('Valid MX records');
  totalWeight += 5;
}

// Final confidence calculation
confidence = Math.max(0, Math.min(100, totalWeight));

// Determine verification result
let finalStatus = 'invalid';
let deliverabilityScore = 0;

if (confidence >= 90 && validCount >= 2) {
  finalStatus = 'verified';
  deliverabilityScore = 95;
} else if (confidence >= 70 && validCount >= 2) {
  finalStatus = 'verified';
  deliverabilityScore = 85;
} else if (confidence >= 50 && validCount >= 1) {
  finalStatus = 'likely_valid';
  deliverabilityScore = 70;
} else if (confidence >= 35) {
  finalStatus = 'risky';
  deliverabilityScore = 40;
} else {
  finalStatus = 'invalid';
  deliverabilityScore = 10;
}

// Special case: catch-all servers
if (nb.result === 'catchall' || zb.status === 'catch-all') {
  finalStatus = 'catch-all';
  deliverabilityScore = Math.min(deliverabilityScore, 50);
}

// Compile final result
const verificationResult = {
  email: email,
  status: finalStatus,
  confidence: confidence,
  deliverabilityScore: deliverabilityScore,
  validCount: validCount,
  totalChecks: 3,
  issues: issues,
  strengths: strengths,
  recommendations: generateRecommendations(finalStatus, issues),
  verifiedAt: new Date().toISOString(),

  // Source data
  neverBounce: nb,
  debounce: db,
  zeroBounce: zb
};

function generateRecommendations(status, issues) {
  const recs = [];

  if (status === 'verified') {
    recs.push('Safe to send - high deliverability');
  } else if (status === 'likely_valid') {
    recs.push('Proceed with caution - monitor bounce rates');
  } else if (status === 'catch-all') {
    recs.push('Test send recommended - cannot guarantee delivery');
  } else if (status === 'risky') {
    recs.push('High risk - consider alternative contact methods');
  } else {
    recs.push('Do not send - email is invalid');
  }

  if (issues.some(i => i.includes('spam trap'))) {
    recs.push('WARNING: Remove immediately to protect sender reputation');
  }

  if (issues.some(i => i.includes('role-based'))) {
    recs.push('Consider finding direct decision-maker email');
  }

  return recs;
}

console.log(`Verification complete: ${email} = ${finalStatus} (${confidence}% confidence)`);

return [{
  json: {
    ...emailData,
    verificationResult: verificationResult
  }
}];

// Compile batch results
const allResults = $input.all().map(item => item.json);

const batchId = allResults[0]?.batchId || 'unknown';

// Statistics
const stats = {
  total: allResults.length,
  verified: allResults.filter(r => r.verificationResult.status === 'verified').length,
  likelyValid: allResults.filter(r => r.verificationResult.status === 'likely_valid').length,
  catchAll: allResults.filter(r => r.verificationResult.status === 'catch-all').length,
  risky: allResults.filter(r => r.verificationResult.status === 'risky').length,
  invalid: allResults.filter(r => r.verificationResult.status === 'invalid').length,
  avgConfidence: (allResults.reduce((sum, r) => sum + r.verificationResult.confidence, 0) / allResults.length).toFixed(2),
  avgDeliverability: (allResults.reduce((sum, r) => sum + r.verificationResult.deliverabilityScore, 0) / allResults.length).toFixed(2)
};

const batchResult = {
  batchId: batchId,
  timestamp: new Date().toISOString(),
  statistics: stats,
  results: allResults.map(r => ({
    propertyId: r.propertyId,
    email: r.email,
    status: r.verificationResult.status,
    confidence: r.verificationResult.confidence,
    deliverabilityScore: r.verificationResult.deliverabilityScore,
    issues: r.verificationResult.issues,
    recommendations: r.verificationResult.recommendations
  })),
  success: true,
  message: `Verified ${stats.total} emails. ${stats.verified} verified, ${stats.invalid} invalid.`
};

console.log('Batch verification complete:', batchResult.message);

return [{ json: batchResult }];

// Save verification results to database
const batchResult = $input.first().json;

console.log(`[DATABASE] Saving verification results for batch ${batchResult.batchId}`);

// In production, update database with verified emails

const saveResult = {
  success: true,
  batchId: batchResult.batchId,
  recordsUpdated: batchResult.statistics.total,
  verifiedEmails: batchResult.statistics.verified,
  timestamp: new Date().toISOString(),
  message: 'Email verification results saved successfully'
};

return [{ json: saveResult }];
